const quote = (step: QuoteStep): StepResult => {
  const policyBasePremium = step.items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );
  return {
    premium:
      policyBasePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE) + PROCESSING_FEE,
  };
};

const runStep = (step: Step): StepResult => quote(step as QuoteStep);

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quote(step);
  throw new Error(`Unsupported step: ${step.op}`);
};

